import json, re
from pathlib import Path

launch = json.load(open('.vscode/launch.json'))
tasks = json.load(open('.vscode/tasks.json'))
doc = Path('docs/windows_build_debug_setup.md').read_text()
cube = Path('scripts/windows_flash_cube.ps1').read_text()
openocd_ps1 = Path('scripts/windows_flash_openocd.ps1').read_text()

cfgs = launch['configurations']
task_by_label = {t['label']: t for t in tasks['tasks']}

findings = []

# AC1 / R1: default F5 first config
c0 = cfgs[0]
if 'Cube flash then ST-LINK' not in c0['name'] or 'default F5' not in c0['name']:
    findings.append(f'AC1 FAIL: first config name unexpected: {c0["name"]}')
if c0.get('servertype') != 'stlink':
    findings.append(f'AC1 FAIL: first servertype={c0.get("servertype")}')
if c0.get('preLaunchTask') != 'openvela: flash debug firmware (CubeProgrammer QSPI)':
    findings.append(f'AC1 FAIL: preLaunchTask={c0.get("preLaunchTask")}')
if c0.get('runToEntryPoint') != 'velaguard_main':
    findings.append(f'AC1 FAIL: runToEntryPoint={c0.get("runToEntryPoint")}')
if c0.get('executable') != '${workspaceFolder}/.debug/nuttx.elf':
    findings.append(f'AC1 FAIL: executable={c0.get("executable")}')

# R1 second attach only
c1 = cfgs[1]
if 'attach only' not in c1['name'] or 'no flash' not in c1['name']:
    findings.append(f'R1 FAIL: second config name: {c1["name"]}')
if c1.get('preLaunchTask'):
    findings.append(f'R1 FAIL: attach-only has preLaunchTask: {c1.get("preLaunchTask")}')
if c1.get('servertype') != 'stlink':
    findings.append(f'R1 FAIL: second servertype')

# R3 third openocd fallback
c2 = cfgs[2]
if 'fallback' not in c2['name'].lower() and 'OpenOCD' not in c2['name']:
    findings.append(f'R3 FAIL: third config: {c2["name"]}')
if c2.get('servertype') != 'openocd':
    findings.append('R3 FAIL: third not openocd')
if c2.get('preLaunchTask'):
    findings.append('R3 FAIL: openocd has preLaunchTask')
if 'openocd_h750_attach.cfg' not in c2.get('configFiles', []):
    findings.append('R3 FAIL: missing openocd_h750_attach.cfg')
if 'set QUADSPI 0' not in c2.get('openOCDPreConfigLaunchCommands', []):
    findings.append('R3 FAIL: QUADSPI not 0')

# R2 all flash tasks use cube
flash_tasks = [t for t in tasks['tasks'] if 'flash' in t['label'].lower()]
for t in flash_tasks:
    args = ' '.join(t.get('args', []))
    if 'windows_flash_cube.ps1' not in args:
        findings.append(f'R2 FAIL: flash task not cube: {t["label"]} -> {args}')
    if 'OpenOCD' in t['label'] and 'alias' not in t['label'].lower() and 'Cube' not in t['label']:
        findings.append(f'R2/AC3 FAIL: misleading OpenOCD flash label: {t["label"]}')

# flash debug depends on build debug
fd = task_by_label.get('openvela: flash debug firmware (CubeProgrammer QSPI)')
if not fd:
    findings.append('missing flash debug task')
elif fd.get('dependsOn') != 'openvela: build debug firmware (Windows -> WSL)':
    findings.append(f'flash debug dependsOn wrong: {fd.get("dependsOn")}')

# AC5 error messages
for needle in [
    'STM32CubeProgrammer CLI was not found',
    'Expected default: D:\\Develop\\STM32CubeCLT\\STM32CubeProgrammer\\bin\\STM32_Programmer_CLI.exe',
    'External loader was not found',
    'MT25TL01G_STM32H750B-DISCO.stldr',
]:
    if needle not in cube:
        findings.append(f'AC5 FAIL: missing error text: {needle}')

# openocd wrapper redirects
if 'windows_flash_cube.ps1' not in openocd_ps1:
    findings.append('openocd wrapper does not call cube')
if 'cannot program dual-QSPI' not in openocd_ps1:
    findings.append('openocd wrapper missing loud note')

# Doc consistency AC4
for name in [c0['name'], c1['name'], c2['name'],
             'openvela: flash debug firmware (CubeProgrammer QSPI)',
             'openvela: flash firmware (CubeProgrammer QSPI)']:
    if name not in doc:
        findings.append(f'AC4 FAIL: doc missing name: {name}')

if '仅作为 attach' not in doc and '仅作为 attach 回退' not in doc and 'attach fallback' not in doc and 'attach 回退' not in doc:
    findings.append('AC4 FAIL: doc does not say OpenOCD is attach-only')

# OpenOCD fallback must not have runToEntryPoint required by design? optional
# First config must not be openocd
if cfgs[0].get('servertype') == 'openocd':
    findings.append('OpenOCD is default F5 — FAIL')

if findings:
    print('FINDINGS:')
    for f in findings:
        print(' -', f)
    raise SystemExit(1)
print('All AC/R static checks: PASS')
print(f'Configs: {[c["name"] for c in cfgs]}')
print(f'Flash tasks: {[t["label"] for t in flash_tasks]}')
PY
